  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2026-11-05');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes issued invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2026-11-10');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.value.number);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  let issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const paid = recordPayment(issued.value, { amount: 20000, date: '2026-10-09' });
  assert.equal(paid.ok, true);

  const result = overdueInvoices([paid.value], '2026-11-10');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, paid.value.number);
