    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'EOM',
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  assert.equal(issued.value.dueDate, '2026-10-31');

  const result = overdueInvoices([issued.value], '2026-11-15');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 15);
});

test('overdueInvoices does not mutate input', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const invoices = [issued.value];
  const original = JSON.parse(JSON.stringify(invoices));

  overdueInvoices(invoices, '2026-11-10');
  assert.deepEqual(invoices, original);
});

